{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A cracked hilltop overlooks a broken skyline of toppled spires and tattered banners. Mara unrolls a map on a stone while the tin fox sniffs the wind and the oracle lamp hovers nearby.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a trap at the main gate.",
      "visual_description": "Close shot of the oil lamp, its single flame-eye flaring orange as it casts long warning shadows across Mara's compass.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver arrives by stepping out of a cracked window.",
      "visual_description": "A tall figure in a clear diving helmet emerges from a shattered shop window, coat shimmering with reflections of broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts the castle gates from the rubble.",
      "visual_description": "A small clockwork fox with blue glass eyes perches atop a heap of stone, its key-wind tail ticking as it watches the iron-barred gates below.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      руки: "",
      "caption": "They find the sleeping tax collector slumped on a guard post.",
      "visual_description": "An official snores against a ledger pillow, stamped papers stuck to his sleeves, oblivious to the ruined courtyard around him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara tries to question the dozing official.",
      "visual_description": "Mara shakes the snoring man's shoulder, her ink-stained fingers smudging his ledger while the tin fox tilts its head, unimpressed.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp points toward the cursed tower.",
      "visual_description": "The lamp's flame-eye stretches into an arrow, indicating a leaning black tower wrapped in faintly glowing chains across the skyline.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver slips through a tall stained window.",
      "visual_description": "The diver's coat ripples as he dives headfirst into a colored window pane as if it were water, leaving rings of light behind him.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Inside, mirrored halls confuse the rescuers.",
      "visual_description": "A corridor of tilted mirrors reflects Mara and the tin fox from impossible angles, with the glass diver's silhouette flickering through several panes at once.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened faces peer from boarded windows above.",
      "visual_description": "Mara looks up at narrow attic windows where pale faces vanish behind shutters. The oracle lamp glows soft blue to calm them.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol marches past in the rain.",
      "visual_description": "From a low alley angle, polished boots and trailing royal banners stomp by while the tin fox flattens against the wet cobbles, eyes dimmed.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "A great roar echoes from the ruins beyond.",
      "visual_description": "Mara and the glass diver freeze on a broken balcony as red light flares over distant rooftops, smoke curling into the shape of vast wings.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp tells them to ignore the false roar.",
      "visual_description": "The lamp swings between the two rescuers, its eye narrowed and stern, its flame shaped like a finger pressed to silent lips.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "They reach a sealed magic door at the tower's base.",
      "visual_description": "A heavy door carved with shifting runes pulses with violet light. Mara traces a route on her map while the tin fox sniffs the threshold.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver dives through the door's polished surface.",
      "visual_description": "The diver plunges into the lacquered door as into still water, ripples spreading outward across the runes as his coat-tails vanish inside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "He pulls the sleeping tax collector out of a locked vault.",
      "visual_description": "The glass diver emerges from a tall mirror dragging the snoring official by the collar, stamped papers fluttering loose, ledger still tucked under one arm.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The team races across the long stone bridge.",
      "visual_description": "Wind whips Mara's coat as she runs across a cracked bridge above a foggy chasm, the tin fox sprinting ahead and the glass diver carrying the still-snoring official.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, the oracle lamp lights the road home.",
      "visual_description": "Dawn breaks over rolling hills behind them. The oracle lamp floats ahead casting warm gold light, while Mara checks her compass and the tin fox's tail ticks steadily.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

